sparql_sna.text:
PREFIX sna: <https://w3id.org/italia/data/opencup-ld/sna/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?neighborId ?neighborLabel ?neighborKind ?rel
WHERE {
  BIND(<https://w3id.org/italia/data/opencup-ld/sna/node/impresa%3A02461490647> AS ?focus)
  {
    ?focus ?p ?neighbor .
    BIND(STRAFTER(STR(?p), "https://w3id.org/italia/data/opencup-ld/sna/") AS ?rel)
  }
  UNION
  {
    ?neighbor ?p ?focus .
    BIND(STRAFTER(STR(?p), "https://w3id.org/italia/data/opencup-ld/sna/") AS ?rel)
  }
  ?neighbor sna:nodeId ?neighborId ;
            rdfs:label ?neighborLabel ;
            sna:kind ?neighborKind .
  FILTER(?rel NOT IN (
    "nodeId","kind","cf","seed","degree","weightedDegree",
    "betweenness","pagerank","community","importoTot"
  ))
}
ORDER BY ?neighborKind ?neighborLabel
LIMIT 15

PREFIX sna: <https://w3id.org/italia/data/opencup-ld/sna/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?id ?label ?kind ?degree
WHERE {
  ?s sna:nodeId ?id ;
     rdfs:label ?label ;
     sna:kind ?kind ;
     sna:degree ?degree .
}
ORDER BY DESC(?degree) ?label
LIMIT 15

sparql_ld.text:
PREFIX pi: <https://w3id.org/italia/PublicInvestment/onto/PublicInvestment/>
PREFIX PCTR: <https://w3id.org/italia/onto/PCTR/>
PREFIX COV: <https://w3id.org/italia/onto/COV/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <https://schema.org/>

SELECT ?title ?about
WHERE {
  ?report a schema:Report .
  OPTIONAL { ?report schema:name ?title }
  OPTIONAL { ?report schema:headline ?title }
  OPTIONAL { ?report schema:about ?about }
}
LIMIT 15
